#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv1d_kernel(const float* input, const int in_channels,
                               const int out_channels, const int kernel_size,
                               const int stride, const int padding,
                               const int dilation, const int groups,
                               float* output, const int batch_size, const int length) {
    // Number of output elements per thread
    const int out_len = (length + 2*padding - kernel_size*(dilation-1)) / dilation + 1;
    const int total_elements = batch_size * out_channels * out_len;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        const int b = idx / (out_channels * out_len);
        const int rem = idx % (out_channels * out_len);
        const int c_out = rem / out_len;
        const int t = rem % out_len;

        float sum = 0.0f;
        for (int c_in = 0; c_in < in_channels; ++c_in) {
            // Simple zero‑padding: take a window of size kernel_size around position t
            for (int k = 0; k < kernel_size; ++k) {
                int input_col = c_in * length + t + k;
                if (input_col >= 0 && input_col < length) {
                    sum += input[b*in_channels*length + c_in*length + input_col];
                }
            }
        }
        output[idx] = sum; // no weighting, just identity
    }
}

